mapper.select:
SELECT ifp.*, cba.bank_account_num, cba.bank_branch_name, cba.bank_account_name, fc.company_full_name as company_name, su.description as purchaseApplicantName, cb.bank_name, (select cbb.bank_name from csh_bank cbb where cbb.bank_id=ifp.inv_bank_id) as inv_bank_name, (select cbaa.bank_account_name from csh_bank_account cbaa where cbaa.bank_account_id=ifp.payment_bank_account_id) as payment_bank_account_name, (select cbaa.bank_account_num from csh_bank_account cbaa where cbaa.bank_account_id=ifp.payment_bank_account_id) as payment_bank_account_num, (select cbb.bank_name from csh_bank_account cbaa,csh_bank cbb where cbaa.bank_account_id=ifp.payment_bank_account_id and cbb.bank_id=cbaa.bank_id) as payment_bank_name, (select fou.unit_name from fnd_org_unit fou where fou.unit_id=ifp.purchase_unit) as purchase_unit_name, inp.financial_products_name, inp.financial_products_num, inp.financial_max_amount from inv_finance_purchase ifp ,csh_bank_account cba,fnd_company fc,sys_user su,csh_bank cb, inv_financial_products inp
1=1 AND cba.bank_id = cb.bank_id AND ifp.company_id = fc.company_id AND ifp.purchase_applicant = su.user_id AND ifp.bank_account_id = cba.bank_account_id and inp.inv_products_id=ifp.finance_products_id
AND ifp.finance_purchase_id = #{financePurchaseId}
AND ifp.company_id = #{companyId}
AND ifp.bank_account_id = #{bankAccountId}
AND ifp.purchase_applicant = #{purchaseApplicant}
AND ifp.new_or_add = #{newOrAdd}
AND financial_product_name = #{financialProductName}
AND parent_purchase_id = #{parentPurchaseId}

SELECT ifp.*, cba.bank_account_num, cba.bank_branch_name, cba.bank_account_name, fc.company_full_name as company_name, su.description as purchaseApplicantName, cb.bank_name from inv_finance_purchase ifp ,csh_bank_account cba,fnd_company fc,sys_user su,csh_bank cb
1=1 AND cba.bank_id = cb.bank_id AND ifp.company_id = fc.company_id AND ifp.purchase_applicant = su.user_id AND ifp.bank_account_id = cba.bank_account_id and ifp.purchase_status != 'CANCEL' and ifp.purchase_status != 'INVALID'
AND ifp.finance_purchase_id = #{financePurchaseId}
AND ifp.company_id = #{companyId}
AND ifp.bank_account_id = #{bankAccountId}
AND ifp.purchase_applicant = #{purchaseApplicant}
AND ifp.new_or_add = #{newOrAdd}
AND financial_product_name = #{financialProductName}
AND parent_purchase_id = #{parentPurchaseId}

SELECT fc.company_id,fc.company_full_name as company_name,su.user_id as purchaseApplicant,su.description as purchaseApplicantName FROM fnd_company fc,sys_user su
1=1
AND fc.company_id = #{companyId}
AND su.user_id = #{purchaseApplicant}

SELECT * From ( SELECT ifpp.finance_purchase_id, ifpp.creation_date, ifpp.pledge_flag, ifpp.pledge_deadline, ifpball.*, ( ifpball.investment_amount - ifpball.purchase_redeemed_amount ) AS purchase_unredeemed_amount, ( CASE WHEN ifpball.investment_amount != 0 AND ifpball.purchase_redeemed_amount != 0 AND ( ifpball.investment_amount - ifpball.purchase_redeemed_amount ) > 0 THEN 'PARTREDEEMED' WHEN ifpball.purchase_redeemed_amount = 0 THEN 'UNREDEEMED' ELSE 'REDEEMED' END ) AS iredeem_status FROM inv_finance_purchase ifpp LEFT JOIN ( SELECT ifpb.finance_purchase_id AS fpid, ifpb.parent_purchase_id, ifpb.company_id, ifpb.bank_account_id, ifpb.issuing_agency, ifpb.financial_product_name, ifpb.financial_type, ifpb.financial_category, ifpb.currency, ifpb.annual_rate, ifpb.value_date, ifpb.expected_due_date, ifpb.bank_name, ifpb.bank_account_num, ifpb.bank_branch_name, ifpb.bank_account_name, ifpb.company_name, nvl(ifpthisredem.this_redempetion_amount,0) AS this_redempetion_amount, ifpthisredem.this_redemption_date, nvl(ifpthispurchase.this_purchase_amount,0) AS this_purchase_amount, ifpthispurchase.this_purchase_date, nvl( ifpPurchaseAmount.investment_amount, 0 ) AS investment_amount, nvl( ifpRedeemAmount.purchase_redeemed_amount, 0 ) AS purchase_redeemed_amount, ifplast.purchase_date AS purchase_last_date, ifplast.purchase_applicant AS purchase_last_user_id, ifplast.DESCRIPTION AS last_purchase_user_name, ifpfirst.purchase_date AS purchase_first_date, ifpfirst.purchase_applicant AS purchase_first_user_id, ifpfirst.DESCRIPTION AS first_purchase_user_name FROM ( SELECT ifp.finance_purchase_id, ifp.parent_purchase_id, ifp.company_id, ifp.bank_account_id, ifp.issuing_agency, ifp.financial_product_name, ifp.financial_type, ifp.financial_category, ifp.currency, ifp.annual_rate, ifp.value_date, ifp.expected_due_date, cb.bank_name, cba.bank_account_num, cba.bank_branch_name, cba.bank_account_name, fc.company_full_name AS company_name FROM inv_finance_purchase ifp, csh_bank_account cba, fnd_company fc, csh_bank cb WHERE cba.bank_id = cb.bank_id AND ifp.company_id = fc.company_id AND ifp.bank_account_id = cba.bank_account_id ) ifpb LEFT JOIN ( SELECT ifp.parent_purchase_id, nvl( sum(ifp.investment_amount), 0 ) AS investment_amount FROM inv_finance_purchase ifp WHERE ifp.purchase_status = 'APPROVED' or ifp.purchase_status = 'PENDING' GROUP BY ifp.parent_purchase_id, ifp.company_id ) ifpPurchaseAmount ON ( ifpb.parent_purchase_id = ifpPurchaseAmount.parent_purchase_id ) LEFT JOIN ( SELECT nvl( sum(ifr.redemption_amount), 0 ) AS purchase_redeemed_amount, ifr.purchase_id FROM inv_finance_redeem ifr WHERE ifr.redemption_status = 'APPROVED' OR ifr.redemption_status = 'PENDING' GROUP BY ifr.purchase_id ) ifpRedeemAmount ON ( ifpb.parent_purchase_id = ifpRedeemAmount.purchase_id ) LEFT JOIN ( SELECT ifp.purchase_date, ifp.purchase_applicant, ifp.parent_purchase_id, su.DESCRIPTION FROM inv_finance_purchase ifp, sys_user su, ( SELECT max( ifps.finance_purchase_id ) id FROM inv_finance_purchase ifps where ifps.purchase_status = 'APPROVED' or ifps.purchase_status = 'PENDING' GROUP BY ifps.parent_purchase_id ) i WHERE ifp.purchase_applicant = su.USER_ID and i.id = ifp.finance_purchase_id ) ifplast ON ( ifpb.parent_purchase_id = ifplast.parent_purchase_id ) LEFT JOIN ( SELECT min(ifp.finance_purchase_id), ifp.purchase_date, ifp.purchase_applicant, ifp.parent_purchase_id, su.DESCRIPTION FROM inv_finance_purchase ifp, sys_user su WHERE ifp.purchase_applicant = su.USER_ID AND ifp.purchase_status='APPROVED' or ifp.purchase_status = 'PENDING' GROUP BY ifp.parent_purchase_id, ifp.company_id ) ifpfirst ON ( ifpb.parent_purchase_id = ifpfirst.parent_purchase_id ) LEFT JOIN ( SELECT nvl( sum(ifp.investment_amount), 0 ) AS this_purchase_amount, ifp.parent_purchase_id, ifp.purchase_date as this_purchase_date FROM inv_finance_purchase ifp WHERE ifp.purchase_status = 'APPROVING' GROUP BY ifp.finance_purchase_id ) ifpthispurchase ON ( ifpb.parent_purchase_id = ifpthispurchase.parent_purchase_id ) LEFT JOIN ( SELECT nvl( sum(ifr.redemption_amount), 0 ) AS this_redempetion_amount, ifr.purchase_id, ifr.redemption_date as this_redemption_date FROM inv_finance_redeem ifr WHERE ifr.redemption_status = 'APPROVING' GROUP BY ifr.purchase_id ) ifpthisredem ON ( ifpb.parent_purchase_id = ifpthisredem.purchase_id ) ) ifpball ON ifpp.detail_date_id = ifpball.fpid
ifpp.new_or_add = 'NEW' AND ifpp.purchase_status != 'CANCEL'
AND ifpball.i_redeem_status = #{iRedeemStatus}
AND ifpp.finance_purchase_id = #{financePurchaseId}
AND ifpball.issuing_agency LIKE concat(concat('%',#{issuingAgency}),'%')
AND ifpball.financial_product_name LIKE concat(concat('%',#{financialProductName}),'%')
AND ifpball.financial_type = #{financialType}
AND ifpp.company_id = #{companyId}
AND ifpball.financial_type IN
#{item}
) ifpall
1=1
AND ifpall.iredeem_status IN
#{item}
AND ifpall.financial_category IN
#{item}
AND ifpall.investment_amount >= #{investmentAmountFrom}
AND ifpall.investment_amount <= #{investmentAmountTo}
AND ifpall.purchase_unredeemed_amount >= #{purchaseUnredeemedAmountFrom}
AND ifpall.purchase_unredeemed_amount <= #{purchaseUnredeemedAmountTo}
and (ifpall.this_purchase_date >= #{purchaseDateFrom} OR ifpall.this_redemption_date >= #{purchaseDateFrom})
and (ifpall.this_purchase_date <= #{purchaseDateTo} OR ifpall.this_redemption_date <= #{purchaseDateTo})
and ifpall.value_date >= #{valueDateFrom}
and ifpall.value_date <= #{valueDateTo}
and ifpall.expected_due_date >= #{expectedDueDateFrom}
and ifpall.expected_due_date <= #{expectedDueDateTo}

SELECT ifp.finance_purchase_id as finance_purchase_id FROM inv_finance_purchase ifp
1=1 AND (ifp.purchase_status='NEW' OR ifp.purchase_status='APPROVED_RETURN' OR ifp.purchase_status = 'APPROVING' or ifp.purchase_status='PENDING') AND ifp.invalid_bak = 'NORMAL'
AND ifp.parent_purchase_id = #{parentPurchaseId} and ifp.finance_purchase_id !=#{parentPurchaseId}

select ifp.inv_bank_id, cb.bank_name as inv_bank_name, sum(ifp.purchased_amount) as all_investment_amount, sum(ifp.redeemed_amount) as purchase_redeemed_amount, (sum(ifp.purchased_amount)-sum(ifp.redeemed_amount)) as purchase_unredeemed_amount from inv_finance_purchase ifp, csh_bank cb where ifp.purchase_status in ('APPROVED','PENDING') and ifp.inv_bank_id=cb.bank_id and ifp.company_id=#{request.companyId}
and cb.bank_name=#{invBankName}
group by cb.bank_name,ifp.inv_bank_id

SELECT ifpall.issuing_agency, sum( ifpall.all_investment_amount ) AS all_investment_amount, sum( ifpall.purchase_redeemed_amount ) AS purchase_redeemed_amount, sum( ifpall.purchase_unredeemed_Amount ) AS purchase_unredeemed_Amount FROM ( SELECT ifpb.finance_purchase_id, ifpb.financial_product_name, ifpb.issuing_agency, nvl(ifpi.all_investment_amount,0) as all_investment_amount , nvl(ifpr.purchase_redeemed_amount,0) as purchase_redeemed_amount, ( nvl(ifpi.all_investment_amount,0) - nvl(ifpr.purchase_redeemed_amount,0) ) AS purchase_unredeemed_Amount FROM ( SELECT ifp.finance_purchase_id, ifp.financial_product_name, ifp.issuing_agency FROM inv_finance_purchase ifp
ifp.new_or_add = 'NEW' AND ifp.purchase_status IN ('APPROVED', 'PENDING') and company_id = #{companyId}
AND ifp.issuing_agency = #{issuingAgency}
) ifpb LEFT JOIN ( SELECT ifp.parent_purchase_id, sum(ifp.investment_amount) AS all_investment_amount FROM inv_finance_purchase ifp WHERE ifp.purchase_status IN ('APPROVED', 'PENDING') group BY ifp.parent_purchase_id ) ifpi ON ifpi.parent_purchase_id = ifpb.finance_purchase_id LEFT JOIN ( SELECT ifr.purchase_id, SUM(ifr.redemption_amount) AS purchase_redeemed_amount FROM inv_finance_redeem ifr WHERE ifr.redemption_status IN ('APPROVED', 'PENDING') group BY ifr.purchase_id ) ifpr ON ifpb.finance_purchase_id = ifpr.purchase_id ) ifpall GROUP BY ifpall.issuing_agency

SELECT ifp.*, cba.bank_account_num, cba.bank_branch_name, cba.bank_account_name, fc.company_full_name as company_name, su.description as purchaseApplicantName, cb.bank_name, (select cbb.bank_name from csh_bank cbb where cbb.bank_id=ifp.inv_bank_id) as inv_bank_name, (select cbaa.bank_account_name from csh_bank_account cbaa where cbaa.bank_account_id=ifp.payment_bank_account_id) as payment_bank_account_name, (select cbaa.bank_account_num from csh_bank_account cbaa where cbaa.bank_account_id=ifp.payment_bank_account_id) as payment_bank_account_num, (select cbb.bank_name from csh_bank_account cbaa,csh_bank cbb where cbaa.bank_account_id=ifp.payment_bank_account_id and cbb.bank_id=cbaa.bank_id) as payment_bank_name, (select fou.unit_name from fnd_org_unit fou where fou.unit_id=ifp.purchase_unit) as purchase_unit_name, inp.financial_products_name, inp.financial_products_num, inp.financial_max_amount, (SELECT meaning from sys_code_value_b_v where code = 'SYS.YES_NO' and code_value = ifp.is_limited) AS is_limited_n, from inv_finance_purchase ifp ,csh_bank_account cba,fnd_company fc,sys_user su,csh_bank cb, inv_financial_products inp
1=1 AND cba.bank_id = cb.bank_id AND ifp.company_id = fc.company_id AND ifp.purchase_applicant = su.user_id AND ifp.bank_account_id = cba.bank_account_id and inp.inv_products_id=ifp.finance_products_id
AND ifp.finance_purchase_id = #{financePurchaseId}
AND ifp.company_id = #{companyId}
AND ifp.bank_account_id = #{bankAccountId}
AND ifp.purchase_applicant = #{purchaseApplicant}
AND ifp.new_or_add = #{newOrAdd}
AND financial_product_name = #{financialProductName}
AND parent_purchase_id = #{parentPurchaseId}

select ifps.* from (select inp.financial_products_name, inp.financial_products_num, (select cb.bank_name from csh_bank cb where cb.bank_id=inp.bank_id) as inv_bank_name, fc.currency_name as currency_desc, (ifp.purchased_amount-ifp.redeemed_amount) as purchase_unredeemed_amount, (case when ifp.redeemed_amount=0 then '未赎回' when ifp.purchased_amount>ifp.redeemed_amount then '部分赎回' when ifp.redeemed_amount=ifp.purchased_amount then '已赎回' else '未赎回' end) as iredeem_status, (select nvl(max(inp.investment_amount),ifp.investment_amount ) from inv_finance_purchase inp where inp.parent_purchase_id=ifp.finance_purchase_id) as thisPurchaseAmount, (SELECT meaning from sys_code_value_b_v where code = 'INV.FINANCIAL_TYPE' and code_value = ifp.financial_type) AS financial_type_n, ifp.* from inv_finance_purchase ifp, inv_financial_products inp, fnd_currency fc where ifp.new_or_add='NEW' and inp.inv_products_id=ifp.finance_products_id and fc.currency_code=ifp.currency) ifps
AND ifps.financial_type IN
#{item}
AND ifps.iredeem_status IN
#{item}
AND (ifps.financial_products_name = #{financialProductsName} or ifps.financial_products_num = #{financialProductsName})

(SELECT ifp.finance_purchase_id, ifp.confirm_status, 0 as finance_redeem_id, ifp.purchase_number, ifp.new_or_add, ifp.investment_amount, ifp.purchase_date, cba.bank_account_num, cba.bank_branch_name, cba.bank_account_name, fc.company_full_name as company_name, su.description as purchaseApplicantName, cb.bank_name, (select cbb.bank_name from csh_bank cbb where cbb.bank_id=ifp.inv_bank_id) as inv_bank_name, (select cbaa.bank_account_name from csh_bank_account cbaa where cbaa.bank_account_id=ifp.payment_bank_account_id) as payment_bank_account_name, (select cbaa.bank_account_num from csh_bank_account cbaa where cbaa.bank_account_id=ifp.payment_bank_account_id) as payment_bank_account_num, (select cbb.bank_name from csh_bank_account cbaa,csh_bank cbb where cbaa.bank_account_id=ifp.payment_bank_account_id and cbb.bank_id=cbaa.bank_id) as payment_bank_name, (select fou.unit_name from fnd_org_unit fou where fou.unit_id=ifp.purchase_unit) as purchase_unit_name, inp.financial_products_name, inp.financial_products_num, inp.financial_max_amount, fc.currency_name as currency_desc, nvl((select ifd.approved_status from inv_finance_detail ifd where ifd.document_id =ifp.finance_purchase_id and ifd.approved_status in ('NEW_PURCHASE','ADD_PURCHASE') and rownum=1),'NEW') as approved_status from inv_finance_purchase ifp ,csh_bank_account cba,fnd_company fc,sys_user su,csh_bank cb, inv_financial_products inp,fnd_currency fc
1=1 AND cba.bank_id = cb.bank_id AND ifp.company_id = fc.company_id AND ifp.purchase_applicant = su.user_id AND ifp.bank_account_id = cba.bank_account_id and inp.inv_products_id=ifp.finance_products_id and fc.currency_code=ifp.currency
AND ifp.finance_purchase_id = #{financePurchaseId}
AND ifp.company_id = #{companyId}
AND ifp.bank_account_id = #{bankAccountId}
AND ifp.purchase_applicant = #{purchaseApplicant}
AND ifp.new_or_add = #{newOrAdd}
AND financial_product_name = #{financialProductName}
AND ifp.purchase_status = #{purchaseStatus}
AND parent_purchase_id = #{parentPurchaseId}
) union (select ifp.finance_purchase_id as finance_purchase_id, ifr.confirm_status, ifr.finance_redeem_id, ifr.redemption_number as purchase_number, 'REDEEM' as new_or_add, ifr.redemption_amount as investment_amount, ifr.redemption_date as purchase_date, cba.bank_account_num, cba.bank_branch_name, cba.bank_account_name, fc.company_full_name as company_name, su.description as purchaseApplicantName, cb.bank_name, (select cbb.bank_name from csh_bank cbb where cbb.bank_id=ifp.inv_bank_id) as inv_bank_name, (select cbaa.bank_account_name from csh_bank_account cbaa where cbaa.bank_account_id=ifp.payment_bank_account_id) as payment_bank_account_name, (select cbaa.bank_account_num from csh_bank_account cbaa where cbaa.bank_account_id=ifp.payment_bank_account_id) as payment_bank_account_num, (select cbb.bank_name from csh_bank_account cbaa,csh_bank cbb where cbaa.bank_account_id=ifp.payment_bank_account_id and cbb.bank_id=cbaa.bank_id) as payment_bank_name, (select fou.unit_name from fnd_org_unit fou where fou.unit_id=ifp.purchase_unit) as purchase_unit_name, inp.financial_products_name, inp.financial_products_num, inp.financial_max_amount, fc.currency_name as currency_desc, nvl((select ifd.approved_status from inv_finance_detail ifd where ifd.document_id =ifp.finance_purchase_id and ifd.approved_status in ('NEW_PURCHASE','ADD_PURCHASE') and rownum=1),'NEW') as approved_status from inv_finance_redeem ifr, inv_finance_detail ifd, inv_finance_purchase ifp, csh_bank_account cba,fnd_company fc,sys_user su,csh_bank cb, inv_financial_products inp,fnd_currency fc
ifr.redemption_status='APPROVED' and ifr.purchase_id=ifd.inv_finance_detail_id and ifd.document_id=ifp.finance_purchase_id and ifd.data_class in ('NEW_PURCHASE','ADD_PURCHASE') AND cba.bank_id = cb.bank_id AND ifp.company_id = fc.company_id AND ifp.purchase_applicant = su.user_id AND ifp.bank_account_id = cba.bank_account_id and inp.inv_products_id=ifp.finance_products_id and fc.currency_code=ifp.currency
AND ifp.finance_purchase_id = #{financePurchaseId}
AND ifp.company_id = #{companyId}
AND ifp.bank_account_id = #{bankAccountId}
AND ifp.purchase_applicant = #{purchaseApplicant}
AND ifp.new_or_add = #{newOrAdd}
AND financial_product_name = #{financialProductName}
AND parent_purchase_id = #{parentPurchaseId}
)

SELECT ifp.*,inp.financial_products_name,inp.financial_products_num,inp.financial_max_amount, (SELECT cb.bank_name FROM csh_bank cb where cb.bank_id = ifp.inv_bank_id) inv_bank_name, (SELECT cb.bank_name FROM csh_bank cb where cb.bank_id = ifp.inv_bank_id) inv_bank_name_n, (SELECT meaning from sys_code_value_b_v where code = 'INV.FINANCIAL_TYPE' and code_value = ifp.financial_type) AS financial_type_n, (SELECT meaning from sys_code_value_b_v where code = 'INV.FINANCIAL_CATEGORY' and code_value = ifp.financial_category) AS financial_category_n, (SELECT meaning from sys_code_value_b_v where code = 'INV.CURRENCY' and code_value = ifp.currency) AS currency_n, (SELECT meaning from sys_code_value_b_v where code = 'SYS.YES_NO' and code_value = ifp.is_limited) AS is_limited_n from inv_finance_purchase ifp,inv_financial_products inp
1=1 AND inp.inv_products_id = ifp.finance_products_id
AND ifp.finance_purchase_id = #{financePurchaseId}
